const fs = require('fs');

const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let pos = 0;

const L = parseInt(tokens[pos++], 10);
const C = parseInt(tokens[pos++], 10);

const grid = Array.from({ length: L }, () => Array(C));
const rowTargets = [];
const namesSet = new Set();

for (let r = 0; r < L; r++) {
    for (let c = 0; c < C; c++) {
        const name = tokens[pos++];
        grid[r][c] = name;
        namesSet.add(name);
    }
    rowTargets.push(BigInt(tokens[pos++]));
}

const colTargets = [];
for (let c = 0; c < C; c++) {
    colTargets.push(BigInt(tokens[pos++]));
}

const names = Array.from(namesSet).sort();
const nameToIdx = new Map();
for (let i = 0; i < names.length; i++) {
    nameToIdx.set(names[i], i);
}

const V = names.length;
const E = L + C;

const counts = Array.from({ length: E }, () => new Array(V).fill(0));

for (let r = 0; r < L; r++) {
    for (let c = 0; c < C; c++) {
        const v = nameToIdx.get(grid[r][c]);
        counts[r][v]++;
        counts[L + c][v]++;
    }
}

const targets = new Array(E);
for (let r = 0; r < L; r++) targets[r] = rowTargets[r];
for (let c = 0; c < C; c++) targets[L + c] = colTargets[c];

const eqPairs = Array.from({ length: E }, () => []);
const varEqs = Array.from({ length: V }, () => []);
const unknownCount = new Array(E).fill(0);

for (let e = 0; e < E; e++) {
    for (let v = 0; v < V; v++) {
        const cnt = counts[e][v];
        if (cnt > 0) {
            eqPairs[e].push([v, cnt]);
            varEqs[v].push([e, cnt]);
            unknownCount[e]++;
        }
    }
}

const knownSum = new Array(E).fill(0n);
const values = new Array(V).fill(null);
const queue = [];

for (let e = 0; e < E; e++) {
    if (unknownCount[e] === 1) queue.push(e);
}

let head = 0;
while (head < queue.length) {
    const e = queue[head++];
    if (unknownCount[e] !== 1) continue;

    let varIdx = -1;
    let mult = 0;

    for (const [v, cnt] of eqPairs[e]) {
        if (values[v] === null) {
            varIdx = v;
            mult = cnt;
            break;
        }
    }

    const val = (targets[e] - knownSum[e]) / BigInt(mult);
    values[varIdx] = val;

    for (const [e2, cnt2] of varEqs[varIdx]) {
        knownSum[e2] += val * BigInt(cnt2);
        unknownCount[e2]--;

        if (unknownCount[e2] === 1) {
            queue.push(e2);
        }
    }
}

const out = [];
for (let i = 0; i < V; i++) {
    out.push(names[i] + ' ' + values[i].toString());
}

console.log(out.join('\n'));
